Queue = class('Queue')

function Queue:ctor(capacity)
    self.capacity = capacity
    self.queue = {}
    self.size = 0
    self.head = -1
    self.rear = -1
end

function Queue:enQueue(element)
    if not element then return end
    if self.size == 0 then
        self.head = 0
        self.rear = 0
    end
    if self.capacity then
        if self.size >= self.capacity then
            print("队列已满")
            return
        end
        self.rear = (self.rear) % self.capacity + 1
    else
        self.rear = self.rear + 1
    end
    self.queue[self.rear] = element
    self.size = self.size + 1
end

function Queue:Count()
    return  self.size;
end

function Queue:deQueue()
    if self.size == 0 then
        print("队列为空")
        return nil
    end
    if self.capacity then
        self.head = (self.head) % self.capacity + 1
    else
        self.head = self.head + 1
    end
    self.size = self.size - 1
    return self.queue[self.head]
end

function Queue:Destroy()
    self:Clear();
    self.capacity = nil
    self.queue = nil
    self.size = nil
    self.head = nil
    self.rear = nil
    self = nil;
end

function Queue:Clear()
    while(self.size > 0)
    do
        local value = self:deQueue();
        value = nil;
    end
end

function Queue:Peek()
    local real_head = self.head + 1;
    return self.queue[real_head];
end